&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p class=&quot;[overflow-wrap:anywhere] whitespace-pre-wrap&quot;&gt;&amp;nbsp;&lt;/p&gt;
&lt;p class=&quot;[overflow-wrap:anywhere] whitespace-pre-wrap&quot;&gt;&lt;strong&gt;Dein Profil&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-start=&quot;3517&quot; data-end=&quot;3600&quot; data-section-id=&quot;122u1ik&quot;&gt;Mindestens 5–6 Jahre Erfahrung im Consulting oder im Fachbereich einer Privatbank&lt;/li&gt;
&lt;li data-start=&quot;3601&quot; data-end=&quot;3684&quot; data-section-id=&quot;xtiqli&quot;&gt;Fundierte Erfahrung im Reporting-, MIS- oder Management-Information-System-Umfeld&lt;/li&gt;
&lt;li data-start=&quot;3685&quot; data-end=&quot;3789&quot; data-section-id=&quot;1ng6h0o&quot;&gt;Tiefes Verständnis der Produkte und Prozesse im Private Banking, Wealth Management oder Retail Banking&lt;/li&gt;
&lt;li data-start=&quot;3790&quot; data-end=&quot;3906&quot; data-section-id=&quot;1xdjbcf&quot;&gt;Erfahrung als Business Analyst oder Functional Analyst in regulatorischen oder fachlichen Transformationsprojekten&lt;/li&gt;
&lt;li data-start=&quot;3907&quot; data-end=&quot;3990&quot; data-section-id=&quot;shefll&quot;&gt;Sehr gute Kenntnisse bankfachlicher KPIs, Management Reporting und Sales Steering&lt;/li&gt;
